import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>{count}</p>
      <button type="button" onClick={() => setCount(c => c + 1)}>Increment</button>
    </div>
  )
}

import { useEffect, useState } from 'react'

export default function FetchUsers() {
  const [users, setUsers] = useState(null)
  const [error, setError] = useState(null)

  useEffect(() => {
    const controller = new AbortController()

    fetch('https://jsonplaceholder.typicode.com/users', { signal: controller.signal })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then(setUsers)
      .catch(err => {
        if (err.name !== 'AbortError') setError(err)
      })

    return () => controller.abort()
  }, [])

  if (error) return <p>Error: {error.message}</p>
  if (!users) return <p>Loading…</p>

  return (
    <ul>
      {users.map(user => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  )
}

import { useState } from 'react'

const columns = [
  { key: 'name', label: 'Name' },
  { key: 'price', label: 'Price' },
  { key: 'qty', label: 'Qty' },
]

export default function FilterTable({ rows = [] }) {
  const [query, setQuery] = useState('')
  const [sort, setSort] = useState({ key: null, asc: true })

  const needle = query.trim().toLowerCase()
  const visible = rows.filter(row => row.name.toLowerCase().includes(needle))

  if (sort.key) {
    const dir = sort.asc ? 1 : -1
    visible.sort((a, b) => {
      const x = a[sort.key]
      const y = b[sort.key]
      const cmp = typeof x === 'string' ? x.localeCompare(y) : x - y
      return cmp * dir
    })
  }

  const total = visible.reduce((sum, row) => sum + row.price * row.qty, 0)

  function toggleSort(key) {
    setSort(prev => (prev.key === key ? { key, asc: !prev.asc } : { key, asc: true }))
  }

  return (
    <div>
      <input
        type="search"
        placeholder="Search by name"
        value={query}
        onChange={e => setQuery(e.target.value)}
      />
      <table>
        <thead>
          <tr>
            {columns.map(col => (
              <th
                key={col.key}
                onClick={() => toggleSort(col.key)}
                aria-sort={sort.key === col.key ? (sort.asc ? 'ascending' : 'descending') : 'none'}
              >
                {col.label}
                {sort.key === col.key && (sort.asc ? ' ▲' : ' ▼')}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {visible.map((row, i) => (
            <tr key={`${row.name}-${i}`}>
              <td>{row.name}</td>
              <td>{row.price}</td>
              <td>{row.qty}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={2}>Total</td>
            <td>{total}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  )
}

export default function Hello({ name }) {
  return <p>Hello, {name}!</p>
}

import { useEffect, useState } from 'react'

async function request(url, options) {
  const res = await fetch(url, options)
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`)
  return res
}

export default function KvBrowser({ baseUrl }) {
  const [keys, setKeys] = useState([])
  const [version, setVersion] = useState(0)
  const [selected, setSelected] = useState(null)
  const [newKey, setNewKey] = useState('')
  const [newValue, setNewValue] = useState('')
  const [error, setError] = useState(null)

  const keyUrl = key => `${baseUrl}/kv/${encodeURIComponent(key)}`

  useEffect(() => {
    const controller = new AbortController()

    request(`${baseUrl}/kv`, { signal: controller.signal })
      .then(res => res.json())
      .then(setKeys)
      .catch(err => {
        if (err.name !== 'AbortError') setError(err.message)
      })

    return () => controller.abort()
  }, [baseUrl, version])

  const reload = () => setVersion(v => v + 1)

  async function show(key) {
    setError(null)
    try {
      const res = await request(keyUrl(key))
      setSelected({ key, value: await res.text() })
    } catch (err) {
      setError(err.message)
    }
  }

  async function save(e) {
    e.preventDefault()
    if (!newKey) return
    setError(null)
    try {
      await request(keyUrl(newKey), { method: 'PUT', body: newValue })
      if (selected?.key === newKey) setSelected({ key: newKey, value: newValue })
      setNewKey('')
      setNewValue('')
    } catch (err) {
      setError(err.message)
    } finally {
      reload()
    }
  }

  async function remove(key) {
    setError(null)
    try {
      await request(keyUrl(key), { method: 'DELETE' })
      if (selected?.key === key) setSelected(null)
    } catch (err) {
      setError(err.message)
    } finally {
      reload()
    }
  }

  return (
    <div>
      {error && <p role="alert">Error: {error}</p>}
      <form onSubmit={save}>
        <input placeholder="Key" value={newKey} onChange={e => setNewKey(e.target.value)} />
        <input placeholder="Value" value={newValue} onChange={e => setNewValue(e.target.value)} />
        <button type="submit">Save</button>
      </form>
      <ul>
        {keys.map(key => (
          <li key={key}>
            <button type="button" onClick={() => show(key)}>{key}</button>
            <button type="button" onClick={() => remove(key)}>Delete</button>
          </li>
        ))}
      </ul>
      {selected && (
        <div>
          <h3>{selected.key}</h3>
          <pre>{selected.value}</pre>
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'

export default function Todo() {
  const [text, setText] = useState('')
  const [items, setItems] = useState([])

  function handleSubmit(e) {
    e.preventDefault()
    const value = text.trim()
    if (!value) return
    setItems(prev => [...prev, { id: crypto.randomUUID(), text: value }])
    setText('')
  }

  function remove(id) {
    setItems(prev => prev.filter(item => item.id !== id))
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={text} onChange={e => setText(e.target.value)} />
        <button type="submit">Add</button>
      </form>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            {item.text}
            <button type="button" onClick={() => remove(item.id)}>Remove</button>
          </li>
        ))}
      </ul>
    </div>
  )
}
